func taggerRegisterUsageCommand() *cli.Command {
	return &cli.Command{
		Name:  "register-usage",
		Usage: "RegisterUsage is used to inform eidos when an external system has tagged a piece of media with entities managed by eidos.",
		Flags: append([]cli.Flag{
			&cli.StringFlag{Name: "content-type", Usage: "ContentType of the media that was tagged."},
			&cli.StringFlag{Name: "context-uri", Usage: "ContentURI is an URI that identified the tagged media."},
			&cli.StringSliceFlag{Name: "entity-uuids", Usage: "The UUIDs of the entities that were used."},
		}, methodFlags()...),
		Action: func(ctx context.Context, cmd *cli.Command) error {
			if cmd.Bool("req-schema") {
				fmt.Println(`{
  "properties": {
    "contentType": {
      "description": "ContentType of the media that was tagged.",
      "type": "string"
    },
    "contextUri": {
      "description": "ContentURI is an URI that identified the tagged media.",
      "type": "string"
    },
    "entityUuids": {
      "description": "The UUIDs of the entities that were used.",
      "items": {
        "type": "string"
      },
      "type": "array"
    }
  },
  "type": "object"
}`)
				return nil
			}

			if cmd.Bool("res-schema") {
				fmt.Println(`{
  "type": "object"
}`)
				return nil
			}

			httpClient, endpoint, err := getClientConfig(ctx, cmd, "eidos2")
			if err != nil {
				return err
			}

			client := eidos.NewTaggerProtobufClient(endpoint, httpClient)

			var req eidos.RegisterUsageRequest

			if err := readRequest(cmd, &req); err != nil {
				return err
			}
			if cmd.String("file") == "" {
				req.ContentType = cmd.String("content-type")
				req.ContextUri = cmd.String("context-uri")
				if v := cmd.StringSlice("entity-uuids"); len(v) > 0 {
					req.EntityUuids = v
				}
			}

			res, err := client.RegisterUsage(ctx, &req)
			if err != nil {
				return fmt.Errorf("call register-usage: %w", err)
			}

			return writeResponse(cmd, res)
		},
	}
}
